const seedSources = [
  {id:1,type:'pdf',title:'The Bitter Lesson',desc:'Escalabilidad, cómputo y métodos generales en sistemas inteligentes.',date:'HOY',tags:['IA','escalabilidad'],links:7,author:'Rich Sutton',url:'incompleteideas.net',summary:'Los métodos que aprovechan el cómputo terminan superando a los enfoques basados en conocimiento humano específico. La lección práctica es construir sistemas que puedan escalar con recursos y datos.',quote:'La búsqueda y el aprendizaje son los dos métodos que parecen escalar arbitrariamente con más cómputo.',related:['Scaling Laws for Neural Language Models','Compute Trends Across Three Eras'],favorite:true},
  {id:2,type:'link',title:'Tools for thought as cultural practices',desc:'Una lectura sobre cómo las herramientas cambian la manera de producir conocimiento.',date:'AYER',tags:['PKM','cultura'],links:5,author:'Maggie Appleton',url:'maggieappleton.com',summary:'Las herramientas para pensar no son contenedores neutrales: codifican prácticas, valores y relaciones sociales. Su valor emerge cuando se integran en hábitos sostenidos.',quote:'Una herramienta se vuelve infraestructura cuando deja de sentirse como una herramienta.',related:['How to Make Yourself Into a Learning Machine','The Garden and the Stream'],favorite:false},
  {id:3,type:'note',title:'Hipótesis: la síntesis es una interfaz',desc:'Notas propias sobre navegación semántica y reducción de fricción.',date:'28 OCT',tags:['síntesis','UX'],links:3,author:'Nota personal',url:'vault://nota/031',summary:'Una buena síntesis no cierra el tema: funciona como interfaz hacia la evidencia, mantiene visibles las tensiones y permite saltar a cada afirmación original.',quote:'El resumen debe ser un mapa de acceso, no el destino final.',related:['Progressive Summarization','Designing for Provenance'],favorite:true},
  {id:4,type:'pdf',title:'Attention Is All You Need',desc:'Arquitectura Transformer y mecanismos de atención para secuencias.',date:'26 OCT',tags:['ML','papers'],links:12,author:'Vaswani et al.',url:'arxiv.org/abs/1706.03762',summary:'El Transformer reemplaza recurrencia y convolución por atención, habilitando mayor paralelización y mejor rendimiento en traducción con menor costo de entrenamiento.',quote:'El modelo se apoya enteramente en un mecanismo de atención para obtener dependencias globales.',related:['The Annotated Transformer','Scaling Laws for Neural Language Models'],favorite:false},
  {id:5,type:'link',title:'A Pattern Language for Knowledge Work',desc:'Patrones recurrentes para capturar, conectar y recuperar ideas.',date:'23 OCT',tags:['sistemas','notas'],links:8,author:'Andy Matuschak',url:'notes.andymatuschak.org',summary:'Las notas duraderas deben escribirse para una audiencia futura, conectarse por ideas específicas y evolucionar mediante uso. El sistema funciona mejor como práctica que como archivo.',quote:'Las notas deben sorprenderte cuando vuelvas a encontrarlas.',related:['Evergreen Notes','Tools for thought as cultural practices'],favorite:false},
  {id:6,type:'note',title:'Preguntas para investigar: memoria externa',desc:'Lista abierta de preguntas sobre cognición distribuida y recuperación.',date:'20 OCT',tags:['preguntas','cognición'],links:2,author:'Nota personal',url:'vault://nota/024',summary:'La línea de investigación compara memoria externa, recuperación contextual y el costo cognitivo de mantener taxonomías manuales.',quote:'¿Qué debe recordar la persona y qué debe recordar el sistema?',related:['The Extended Mind','Where Good Ideas Come From'],favorite:false}
];
const STORAGE_KEY='research-vault-v2';
const safeText=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
let sources=loadSources(),selected=sources[0]?.id,filter='all',currentView='library';
const cards=document.querySelector('#cards'),detail=document.querySelector('#detail'),search=document.querySelector('#search');
const labels={pdf:'PDF',link:'ENLACE',note:'NOTA'};
function loadSources(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));return Array.isArray(saved)&&saved.length?saved:structuredClone(seedSources)}catch{return structuredClone(seedSources)}}
function persist(){localStorage.setItem(STORAGE_KEY,JSON.stringify(sources));document.querySelector('#syncStatus').textContent=`Guardado · ${new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}`;updateStats()}
function updateStats(){document.querySelector('#sourceCount').textContent=sources.length;document.querySelector('#relationCount').textContent=sources.reduce((n,s)=>n+(s.related?.length||0),0);document.querySelector('#favoriteCount').textContent=sources.filter(s=>s.favorite).length;document.querySelectorAll('.tab').forEach(t=>{const b=t.querySelector('b');if(b)b.textContent=t.dataset.filter==='all'?sources.length:sources.filter(s=>s.type===t.dataset.filter).length})}
function visibleSources(){const q=search.value.trim().toLowerCase();return sources.filter(s=>(currentView!=='favorites'||s.favorite)&&(filter==='all'||s.type===filter)&&(`${s.title} ${s.desc} ${s.tags.join(' ')} ${s.author}`.toLowerCase().includes(q)))}
function suggestionsFor(source){const current=new Set((source.related||[]).map(x=>x.toLowerCase()));return sources.filter(x=>x.id!==source.id&&!current.has(x.title.toLowerCase())).map(x=>({source:x,shared:(x.tags||[]).filter(t=>(source.tags||[]).includes(t))})).filter(x=>x.shared.length).sort((a,b)=>b.shared.length-a.shared.length).slice(0,3)}
function renderCards(){const list=visibleSources();cards.innerHTML=list.map(s=>`<article class="card ${s.id===selected?'selected':''}" data-id="${s.id}"><div class="card-top"><span class="type ${s.type}">${labels[s.type]}</span><button class="favorite ${s.favorite?'on':''}" data-favorite="${s.id}" aria-label="Destacar ${safeText(s.title)}">${s.favorite?'◆':'◇'}</button><span class="date">${safeText(s.date)}</span></div><h3>${safeText(s.title)}</h3><p>${safeText(s.desc)}</p><div class="tags">${s.tags.map(t=>`<span class="tag">${safeText(t)}</span>`).join('')}<span class="connections">⌘ ${s.links}</span></div></article>`).join('')||'<div class="empty"><strong>No hay fuentes aquí</strong><span>Prueba otro filtro o añade una nueva entrada.</span></div>';document.querySelectorAll('.card').forEach(c=>c.onclick=e=>{if(e.target.closest('.favorite'))return;selected=+c.dataset.id;renderCards();renderDetail()});document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite(+b.dataset.favorite)})}
function renderDetail(){const s=sources.find(x=>x.id===selected);if(!s){detail.innerHTML='<div class="detail-body">Selecciona una fuente.</div>';return}const suggestions=suggestionsFor(s);detail.innerHTML=`<div class="detail-cover"></div><div class="detail-body"><div class="detail-actions"><span class="type ${s.type}">${labels[s.type]}</span><button class="favorite ${s.favorite?'on':''}" id="detailFavorite">${s.favorite?'◆ Destacada':'◇ Destacar'}</button></div><h2>${safeText(s.title)}</h2><div class="source-link">${safeText(s.author)} · ${safeText(s.url)}</div><div class="summary"><h4>RESUMEN SINTÉTICO</h4><p>${safeText(s.summary)} <span class="cite">[1]</span></p></div><div class="quote">“${safeText(s.quote)}” <span class="cite">[fuente]</span></div><div class="related"><h4>RELACIONES · ${s.related.length}</h4>${s.related.map((r,i)=>`<div class="related-item"><i style="background:${i?'#c6a849':'#e77b45'}"></i><span>${safeText(r)}</span></div>`).join('')||'<p class="muted-line">Todavía no hay relaciones confirmadas.</p>'}</div>${suggestions.length?`<div class="suggestions"><h4>CONEXIONES SUGERIDAS</h4>${suggestions.map(x=>`<button data-connect="${x.source.id}"><span>${safeText(x.source.title)}</span><small>${x.shared.map(safeText).join(' · ')}</small><b>＋</b></button>`).join('')}</div>`:''}<button class="danger" id="deleteBtn">Eliminar del vault</button></div>`;document.querySelector('#detailFavorite').onclick=()=>toggleFavorite(s.id);document.querySelectorAll('[data-connect]').forEach(btn=>btn.onclick=()=>{const target=sources.find(x=>x.id===+btn.dataset.connect);if(!target)return;s.related??=[];s.related.push(target.title);s.links=(s.links||0)+1;persist();renderCards();renderDetail();showToast('Conexión añadida')});document.querySelector('#deleteBtn').onclick=()=>{if(!confirm(`¿Eliminar “${s.title}”?`))return;sources=sources.filter(x=>x.id!==s.id);selected=sources[0]?.id;persist();renderCards();renderDetail();showToast('Fuente eliminada')}}
function toggleFavorite(id){const s=sources.find(x=>x.id===id);if(!s)return;s.favorite=!s.favorite;persist();renderCards();renderDetail();showToast(s.favorite?'Añadida a destacados':'Quitada de destacados')}
function setView(view){currentView=view;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));document.querySelector('#libraryView').hidden=view==='graph';document.querySelector('#graphView').hidden=view!=='graph';document.querySelector('h1').innerHTML=view==='graph'?'Mapa <span>de conocimiento</span>':view==='favorites'?'Fuentes <span>destacadas</span>':'Biblioteca <span>conectada</span>';if(view==='graph')renderGraph();else renderCards()}
function renderGraph(){const canvas=document.querySelector('#graphCanvas'),nodes=sources.slice(0,12),pos=new Map(nodes.map((s,i)=>[s.id,{x:120+(i%4)*220,y:90+Math.floor(i/4)*170}])),edges=[];nodes.forEach((s,i)=>nodes.slice(i+1).forEach(t=>{const explicit=(s.related||[]).includes(t.title)||(t.related||[]).includes(s.title),shared=(s.tags||[]).some(tag=>(t.tags||[]).includes(tag));if(explicit||shared)edges.push({a:s.id,b:t.id,explicit})}));canvas.innerHTML=`<svg viewBox="0 0 900 520" role="img" aria-label="Mapa de relaciones reales">${edges.map(e=>{const a=pos.get(e.a),b=pos.get(e.b);return `<line class="${e.explicit?'confirmed':'suggested'}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`}).join('')}</svg>${nodes.map((s,i)=>`<button class="graph-node ${s.type}" style="left:${8+(i%4)*25}%;top:${12+Math.floor(i/4)*32}%" data-node="${s.id}"><small>${labels[s.type]}</small>${safeText(s.title)}</button>`).join('')}`;document.querySelectorAll('[data-node]').forEach(n=>n.onclick=()=>{selected=+n.dataset.node;setView('library');renderDetail()})}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelector('.tab.active')?.classList.remove('active');t.classList.add('active');filter=t.dataset.filter;renderCards()});
document.querySelectorAll('.nav[data-view]').forEach(n=>n.onclick=()=>setView(n.dataset.view));search.oninput=()=>{if(currentView==='graph')setView('library');renderCards()};
document.querySelector('#viewToggle').onclick=()=>cards.classList.toggle('list');
const dialog=document.querySelector('#addDialog');document.querySelector('#addBtn').onclick=()=>dialog.showModal();
document.querySelector('#saveBtn').onclick=e=>{const form=document.querySelector('#addForm');if(!form.reportValidity()){e.preventDefault();return}const fd=new FormData(form),content=fd.get('content')||'';sources.unshift({id:Date.now(),type:fd.get('kind'),title:fd.get('title'),desc:(content||'Nueva fuente añadida al vault.').slice(0,120),date:'AHORA',tags:(fd.get('tags')||'sin etiqueta').split(',').map(x=>x.trim()).filter(Boolean),links:0,author:'Añadido por ti',url:fd.get('kind')==='link'?content:'vault://fuente-local',summary:'Pendiente de síntesis. La fuente ya forma parte de tu biblioteca local.',quote:'Pendiente de extracción y análisis.',related:[],favorite:false});selected=sources[0].id;persist();setTimeout(()=>{renderCards();renderDetail();form.reset();showToast('Fuente guardada en este navegador')},0)};
document.querySelector('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),sources},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`research-vault-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);showToast('Copia del vault exportada')};
document.querySelector('#importBtn').onclick=()=>document.querySelector('#importFile').click();document.querySelector('#importFile').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text()),incoming=Array.isArray(data)?data:data.sources;if(!Array.isArray(incoming))throw new Error();sources=incoming;selected=sources[0]?.id;persist();renderCards();renderDetail();showToast('Vault importado correctamente')}catch{showToast('El archivo no es un vault válido')}e.target.value=''};
function showToast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
updateStats();renderCards();renderDetail();

